File: index.html
   1 | <!DOCTYPE html>
   2 | <html lang="tr" dir="ltr">
   3 | <head>
   4 | <meta charset="UTF-8" />
   5 | <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
   6 | <title>Dijivoo — Dijital Dünyaya Açılan Kapınız</title>
   7 | <link rel="preconnect" href="https://fonts.googleapis.com"/>
   8 | <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin/>
   9 | <link href="https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Sans:ital,wght@0,300;0,400;0,500;1,300&family=Noto+Kufi+Arabic:wght@300;400;600;700&display=swap" rel="stylesheet"/>
  10 | <style>
  11 |   /* ===== CSS VARIABLES ===== */
  12 |   :root {
  13 |     --teal: #1BA88A;
  14 |     --teal-light: #24D4AF;
  15 |     --teal-dark: #0E7A65;
  16 |     --slate: #2C4A5A;
  17 |     --slate-light: #3D5E72;
  18 |     --bg: #080E12;
  19 |     --bg2: #0D1A22;
  20 |     --bg3: #101F28;
  21 |     --surface: rgba(28, 55, 70, 0.45);
  22 |     --surface2: rgba(27, 168, 138, 0.08);
  23 |     --text: #E8F0F5;
  24 |     --text-dim: #7BA3B8;
  25 |     --text-faint: #3D6478;
  26 |     --border: rgba(27, 168, 138, 0.2);
  27 |     --border-bright: rgba(27, 168, 138, 0.5);
  28 |     --font-main: 'Syne', sans-serif;
  29 |     --font-body: 'DM Sans', sans-serif;
  30 |     --font-ar: 'Noto Kufi Arabic', sans-serif;
  31 |   }
  32 | 
  33 |   /* ===== RESET ===== */
  34 |   *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  35 |   html { scroll-behavior: smooth; }
  36 |   body {
  37 |     background: var(--bg);
  38 |     color: var(--text);
  39 |     font-family: var(--font-body);
  40 |     overflow-x: hidden;
  41 |   }
  42 |   a { color: inherit; text-decoration: none; }
  43 |   img { max-width: 100%; display: block; }
  44 | 
  45 | 
  46 |   /* ===== CANVAS BACKGROUND ===== */
  47 |   #bg-canvas {
  48 |     position: fixed; inset: 0;
  49 |     z-index: 0; pointer-events: none;
  50 |     opacity: 0.35;
  51 |   }
  52 | 
  53 |   /* ===== SCROLLBAR ===== */
  54 |   ::-webkit-scrollbar { width: 4px; }
  55 |   ::-webkit-scrollbar-track { background: var(--bg); }
  56 |   ::-webkit-scrollbar-thumb { background: var(--teal-dark); border-radius: 2px; }
  57 | 
  58 |   /* ===== SCROLL PROGRESS ===== */
  59 |   #scroll-progress {
  60 |     position: fixed; top: 0; left: 0;
  61 |     height: 2px; background: linear-gradient(90deg, var(--teal-dark), var(--teal-light));
  62 |     z-index: 999; transition: width 0.1s;
  63 |   }
  64 | 
  65 |   /* ===== NAVIGATION ===== */
  66 |   nav {
  67 |     position: fixed; top: 0; left: 0; right: 0;
  68 |     z-index: 100;
  69 |     padding: 0 clamp(20px, 5vw, 80px);
  70 |     height: 72px;
  71 |     display: flex; align-items: center; justify-content: space-between;
  72 |     background: rgba(8, 14, 18, 0.75);
  73 |     backdrop-filter: blur(20px);
  74 |     border-bottom: 1px solid var(--border);
  75 |     transition: all 0.4s;
  76 |   }
  77 |   nav.scrolled {
  78 |     height: 60px;
  79 |     border-bottom-color: var(--border-bright);
  80 |     box-shadow: 0 8px 40px rgba(0,0,0,0.4);
  81 |   }
  82 |   .nav-logo {
  83 |     height: 100px;
  84 |     filter: drop-shadow(0 0 12px rgba(27, 168, 138, 0.5));
  85 |     transition: filter 0.3s;
  86 |   }
  87 |   .nav-logo:hover { filter: drop-shadow(0 0 20px rgba(36, 212, 175, 0.7)); }
  88 |   .nav-links {
  89 |     display: flex; gap: 32px; list-style: none;
  90 |     align-items: center;
  91 |   }
  92 |   .nav-links a {
  93 |     font-family: var(--font-main);
  94 |     font-size: 0.85rem; font-weight: 600;
  95 |     letter-spacing: 0.08em;
  96 |     color: var(--text-dim);
  97 |     text-transform: uppercase;
  98 |     position: relative;
  99 |     transition: color 0.3s;
 100 |   }
 101 |   .nav-links a::after {
 102 |     content: ''; position: absolute; bottom: -4px; left: 0; right: 0;
 103 |     height: 1px; background: var(--teal-light);
 104 |     transform: scaleX(0); transform-origin: left;
 105 |     transition: transform 0.35s cubic-bezier(0.23,1,0.32,1);
 106 |   }
 107 |   .nav-links a:hover { color: var(--teal-light); }
 108 |   .nav-links a:hover::after { transform: scaleX(1); }
 109 | 
 110 |   .lang-switcher {
 111 |     display: flex; gap: 6px; align-items: center;
 112 |   }
 113 |   .lang-btn {
 114 |     background: none; border: 1px solid var(--border);
 115 |     color: var(--text-dim);
 116 |     padding: 4px 10px; border-radius: 20px;
 117 |     font-family: var(--font-body); font-size: 0.75rem;
 118 |     transition: all 0.3s;
 119 |   }
 120 |   .lang-btn.active, .lang-btn:hover {
 121 |     background: var(--teal-dark); border-color: var(--teal);
 122 |     color: var(--text);
 123 |   }
 124 | 
 125 |   .hamburger {
 126 |     display: none; flex-direction: column; gap: 5px;
 127 |     background: none; border: none; padding: 4px;
 128 |   }
 129 |   .hamburger span {
 130 |     display: block; width: 24px; height: 2px;
 131 |     background: var(--teal); border-radius: 2px;
 132 |     transition: all 0.35s;
 133 |   }
 134 |   .mobile-menu {
 135 |     display: none; position: fixed;
 136 |     top: 72px; left: 0; right: 0; bottom: 0;
 137 |     background: rgba(8,14,18,0.97);
 138 |     backdrop-filter: blur(30px);
 139 |     z-index: 99;
 140 |     flex-direction: column; align-items: center; justify-content: center;
 141 |     gap: 36px;
 142 |   }
 143 |   .mobile-menu.open { display: flex; }
 144 |   .mobile-menu a {
 145 |     font-family: var(--font-main);
 146 |     font-size: 2rem; font-weight: 700;
 147 |     color: var(--text-dim); letter-spacing: 0.05em;
 148 |     transition: color 0.3s;
 149 |   }
 150 |   .mobile-menu a:hover { color: var(--teal-light); }
 151 | 
 152 |   /* ===== SECTION BASE ===== */
 153 |   section {
 154 |     position: relative; z-index: 1;
 155 |     overflow: hidden;
 156 |   }
 157 | 
 158 |   /* ===== HERO ===== */
 159 |   #hero {
 160 |     min-height: 100vh;
 161 |     display: flex; flex-direction: column;
 162 |     align-items: center; justify-content: center;
 163 |     padding: 100px clamp(20px, 8vw, 140px) 80px;
 164 |     text-align: center;
 165 |   }
 166 |   .hero-eyebrow {
 167 |     display: inline-flex; align-items: center; gap: 10px;
 168 |     background: var(--surface2);
 169 |     border: 1px solid var(--border);
 170 |     border-radius: 100px;
 171 |     padding: 6px 18px;
 172 |     font-size: 0.78rem; font-weight: 500; letter-spacing: 0.12em;
 173 |     color: var(--teal-light); text-transform: uppercase;
 174 |     margin-bottom: 32px;
 175 |     opacity: 0; transform: translateY(20px);
 176 |     animation: fadeUp 0.8s 0.2s forwards;
 177 |   }
 178 |   .hero-eyebrow .dot {
 179 |     width: 6px; height: 6px; background: var(--teal-light);
 180 |     border-radius: 50%; animation: pulse 2s infinite;
 181 |   }
 182 |   @keyframes pulse {
 183 |     0%, 100% { opacity: 1; transform: scale(1); }
 184 |     50% { opacity: 0.4; transform: scale(0.6); }
 185 |   }
 186 | 
 187 |   .hero-title {
 188 |     font-family: var(--font-main);
 189 |     font-size: clamp(3rem, 8vw, 7rem);
 190 |     font-weight: 800; line-height: 1.0;
 191 |     letter-spacing: -0.03em;
 192 |     margin-bottom: 28px;
 193 |     opacity: 0; transform: translateY(30px);
 194 |     animation: fadeUp 0.9s 0.4s forwards;
 195 |   }
 196 |   .hero-title .accent {
 197 |     background: linear-gradient(135deg, var(--teal-light) 0%, var(--teal) 50%, var(--teal-dark) 100%);
 198 |     -webkit-background-clip: text; background-clip: text;
 199 |     -webkit-text-fill-color: transparent;
 200 |     position: relative;
 201 |   }
 202 |   .hero-title .accent::after {
 203 |     content: '';
 204 |     position: absolute; bottom: -4px; left: 0; right: 0;
 205 |     height: 3px;
 206 |     background: linear-gradient(90deg, transparent, var(--teal-light), transparent);
 207 |     border-radius: 2px;
 208 |     animation: shimmer 3s ease-in-out infinite;
 209 |   }
 210 |   @keyframes shimmer {
 211 |     0%, 100% { opacity: 0.3; transform: scaleX(0.7); }
 212 |     50% { opacity: 1; transform: scaleX(1); }
 213 |   }
 214 | 
 215 |   .hero-desc {
 216 |     font-size: clamp(1rem, 2vw, 1.25rem);
 217 |     line-height: 1.75;
 218 |     color: var(--text-dim);
 219 |     max-width: 680px;
 220 |     margin: 0 auto 48px;
 221 |     opacity: 0; transform: translateY(20px);
 222 |     animation: fadeUp 0.9s 0.6s forwards;
 223 |   }
 224 | 
 225 |   .hero-cta {
 226 |     display: flex; gap: 16px; flex-wrap: wrap; justify-content: center;
 227 |     opacity: 0; transform: translateY(20px);
 228 |     animation: fadeUp 0.9s 0.8s forwards;
 229 |   }
 230 |   .btn-primary {
 231 |     background: linear-gradient(135deg, var(--teal), var(--teal-dark));
 232 |     color: #fff; border: none;
 233 |     padding: 14px 36px; border-radius: 6px;
 234 |     font-family: var(--font-main); font-size: 0.9rem; font-weight: 700;
 235 |     letter-spacing: 0.06em; text-transform: uppercase;
 236 |     position: relative; overflow: hidden;
 237 |     transition: transform 0.3s, box-shadow 0.3s;
 238 |     box-shadow: 0 0 30px rgba(27,168,138,0.3);
 239 |   }
 240 |   .btn-primary::before {
 241 |     content: '';
 242 |     position: absolute; inset: 0;
 243 |     background: linear-gradient(135deg, var(--teal-light), var(--teal));
 244 |     opacity: 0; transition: opacity 0.35s;
 245 |   }
 246 |   .btn-primary:hover { transform: translateY(-3px); box-shadow: 0 8px 40px rgba(27,168,138,0.5); }
 247 |   .btn-primary:hover::before { opacity: 1; }
 248 |   .btn-primary span { position: relative; z-index: 1; }
 249 | 
 250 |   .btn-ghost {
 251 |     background: none;
 252 |     border: 1px solid var(--border-bright);
 253 |     color: var(--text); padding: 14px 36px; border-radius: 6px;
 254 |     font-family: var(--font-main); font-size: 0.9rem; font-weight: 600;
 255 |     letter-spacing: 0.06em; text-transform: uppercase;
 256 |     transition: all 0.35s;
 257 |   }
 258 |   .btn-ghost:hover {
 259 |     background: var(--surface2);
 260 |     border-color: var(--teal-light);
 261 |     color: var(--teal-light);
 262 |     transform: translateY(-3px);
 263 |   }
 264 | 
 265 |   .scroll-hint {
 266 |     position: absolute; bottom: 36px; left: 50%; transform: translateX(-50%);
 267 |     display: flex; flex-direction: column; align-items: center; gap: 8px;
 268 |     opacity: 0; animation: fadeUp 1s 1.4s forwards;
 269 |   }
 270 |   .scroll-hint span { font-size: 0.7rem; letter-spacing: 0.15em; color: var(--text-faint); text-transform: uppercase; }
 271 |   .scroll-line {
 272 |     width: 1px; height: 40px;
 273 |     background: linear-gradient(to bottom, var(--teal), transparent);
 274 |     animation: scrollDrop 2s ease-in-out infinite;
 275 |   }
 276 |   @keyframes scrollDrop {
 277 |     0% { transform: scaleY(0); transform-origin: top; }
 278 |     50% { transform: scaleY(1); transform-origin: top; }
 279 |     51% { transform: scaleY(1); transform-origin: bottom; }
 280 |     100% { transform: scaleY(0); transform-origin: bottom; }
 281 |   }
 282 | 
 283 |   @keyframes fadeUp {
 284 |     to { opacity: 1; transform: translateY(0); }
 285 |   }
 286 | 
 287 |   /* ===== SECTION REVEAL ANIMATIONS ===== */
 288 |   .reveal {
 289 |     opacity: 0;
 290 |     transform: translateY(60px);
 291 |     transition: opacity 0.9s cubic-bezier(0.23,1,0.32,1),
 292 |                 transform 0.9s cubic-bezier(0.23,1,0.32,1);
 293 |   }
 294 |   .reveal.visible { opacity: 1; transform: translateY(0); }
 295 |   .reveal-left {
 296 |     opacity: 0; transform: translateX(-60px);
 297 |     transition: opacity 0.9s cubic-bezier(0.23,1,0.32,1),
 298 |                 transform 0.9s cubic-bezier(0.23,1,0.32,1);
 299 |   }
 300 |   .reveal-left.visible { opacity: 1; transform: translateX(0); }
 301 |   .reveal-right {
 302 |     opacity: 0; transform: translateX(60px);
 303 |     transition: opacity 0.9s cubic-bezier(0.23,1,0.32,1),
 304 |                 transform 0.9s cubic-bezier(0.23,1,0.32,1);
 305 |   }
 306 |   .reveal-right.visible { opacity: 1; transform: translateX(0); }
 307 | 
 308 |   /* Stagger delays */
 309 |   .delay-1 { transition-delay: 0.1s; }
 310 |   .delay-2 { transition-delay: 0.2s; }
 311 |   .delay-3 { transition-delay: 0.3s; }
 312 |   .delay-4 { transition-delay: 0.4s; }
 313 |   .delay-5 { transition-delay: 0.5s; }
 314 |   .delay-6 { transition-delay: 0.6s; }
 315 | 
 316 |   /* ===== SECTION HEADINGS ===== */
 317 |   .section-label {
 318 |     display: inline-flex; align-items: center; gap: 10px;
 319 |     font-size: 0.75rem; font-weight: 600; letter-spacing: 0.15em;
 320 |     text-transform: uppercase; color: var(--teal);
 321 |     margin-bottom: 16px;
 322 |   }
 323 |   .section-label::before {
 324 |     content: ''; width: 28px; height: 1px;
 325 |     background: var(--teal); display: block;
 326 |   }
 327 |   .section-title {
 328 |     font-family: var(--font-main);
 329 |     font-size: clamp(2rem, 4.5vw, 3.6rem);
 330 |     font-weight: 800; line-height: 1.1;
 331 |     letter-spacing: -0.02em;
 332 |     margin-bottom: 20px;
 333 |   }
 334 |   .section-title .accent {
 335 |     background: linear-gradient(135deg, var(--teal-light), var(--teal));
 336 |     -webkit-background-clip: text; background-clip: text;
 337 |     -webkit-text-fill-color: transparent;
 338 |   }
 339 |   .section-sub {
 340 |     font-size: 1.05rem; color: var(--text-dim); line-height: 1.7;
 341 |     max-width: 560px;
 342 |   }
 343 | 
 344 |   /* ===== DIVIDER ===== */
 345 |   .section-divider {
 346 |     height: 1px;
 347 |     background: linear-gradient(90deg, transparent, var(--border-bright), transparent);
 348 |     margin: 0 clamp(20px, 8vw, 140px);
 349 |   }
 350 | 
 351 |   /* ===== SERVICES ===== */
 352 |   #services {
 353 |     padding: 120px clamp(20px, 8vw, 140px);
 354 |     background: var(--bg2);
 355 |   }
 356 |   .services-header { margin-bottom: 72px; }
 357 | 
 358 |   .services-grid {
 359 |     display: grid;
 360 |     grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
 361 |     gap: 24px;
 362 |   }
 363 |   .service-card {
 364 |     background: var(--surface);
 365 |     border: 1px solid var(--border);
 366 |     border-radius: 16px;
 367 |     padding: 36px 30px;
 368 |     position: relative; overflow: hidden;
 369 |     transition: border-color 0.4s, transform 0.4s, box-shadow 0.4s;
 370 |     backdrop-filter: blur(12px);
 371 |   }
 372 |   .service-card::before {
 373 |     content: '';
 374 |     position: absolute; inset: 0;
 375 |     background: radial-gradient(ellipse at 20% 20%, rgba(27,168,138,0.12), transparent 70%);
 376 |     opacity: 0; transition: opacity 0.5s;
 377 |   }
 378 |   .service-card:hover { 
 379 |     border-color: var(--border-bright);
 380 |     transform: translateY(-8px);
 381 |     box-shadow: 0 24px 60px rgba(0,0,0,0.4), 0 0 0 1px var(--border-bright);
 382 |   }
 383 |   .service-card:hover::before { opacity: 1; }
 384 | 
 385 |   .service-icon {
 386 |     width: 56px; height: 56px;
 387 |     background: linear-gradient(135deg, rgba(27,168,138,0.25), rgba(27,168,138,0.08));
 388 |     border: 1px solid var(--border-bright);
 389 |     border-radius: 14px;
 390 |     display: flex; align-items: center; justify-content: center;
 391 |     font-size: 1.6rem;
 392 |     margin-bottom: 24px;
 393 |     transition: transform 0.4s, box-shadow 0.4s;
 394 |   }
 395 |   .service-card:hover .service-icon {
 396 |     transform: scale(1.1) rotate(-5deg);
 397 |     box-shadow: 0 8px 24px rgba(27,168,138,0.3);
 398 |   }
 399 |   .service-title {
 400 |     font-family: var(--font-main);
 401 |     font-size: 1.15rem; font-weight: 700;
 402 |     margin-bottom: 12px; color: var(--text);
 403 |   }
 404 |   .service-desc {
 405 |     font-size: 0.9rem; line-height: 1.7;
 406 |     color: var(--text-dim);
 407 |   }
 408 |   .service-tag {
 409 |     display: inline-block;
 410 |     margin-top: 20px;
 411 |     background: var(--surface2);
 412 |     border: 1px solid var(--border);
 413 |     border-radius: 100px;
 414 |     padding: 3px 12px;
 415 |     font-size: 0.72rem; color: var(--teal); letter-spacing: 0.1em;
 416 |     text-transform: uppercase;
 417 |   }
 418 |   .service-card .corner-glow {
 419 |     position: absolute; bottom: -20px; right: -20px;
 420 |     width: 80px; height: 80px;
 421 |     background: radial-gradient(circle, rgba(27,168,138,0.3), transparent 70%);
 422 |     border-radius: 50%;
 423 |     transition: all 0.5s;
 424 |   }
 425 |   .service-card:hover .corner-glow { width: 120px; height: 120px; }
 426 | 
 427 |   /* ===== WORKS ===== */
 428 |   #works {
 429 |     padding: 120px clamp(20px, 8vw, 140px);
 430 |     background: var(--bg);
 431 |   }
 432 |   .works-header { margin-bottom: 72px; }
 433 | 
 434 |   .works-grid {
 435 |     display: grid;
 436 |     grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
 437 |     gap: 28px;
 438 |   }
 439 |   .work-card {
 440 |     background: var(--bg3);
 441 |     border: 1px solid var(--border);
 442 |     border-radius: 20px;
 443 |     overflow: hidden;
 444 |     transition: transform 0.45s cubic-bezier(0.23,1,0.32,1),
 445 |                 border-color 0.4s, box-shadow 0.45s;
 446 |   }
 447 |   .work-card:hover {
 448 |     transform: translateY(-12px) scale(1.01);
 449 |     border-color: var(--border-bright);
 450 |     box-shadow: 0 32px 80px rgba(0,0,0,0.5), 0 0 40px rgba(27,168,138,0.1);
 451 |   }
 452 |   .work-preview {
 453 |     position: relative; height: 220px; overflow: hidden;
 454 |     background: linear-gradient(135deg, var(--slate), var(--bg2));
 455 |   }
 456 |   .work-preview img {
 457 |     width: 100%; height: 100%; object-fit: cover;
 458 |     transition: transform 0.6s cubic-bezier(0.23,1,0.32,1), filter 0.4s;
 459 |     filter: brightness(0.85);
 460 |   }
 461 |   .work-card:hover .work-preview img {
 462 |     transform: scale(1.08);
 463 |     filter: brightness(1);
 464 |   }
 465 |   .work-overlay {
 466 |     position: absolute; inset: 0;
 467 |     background: linear-gradient(to top, rgba(8,14,18,0.9) 0%, rgba(8,14,18,0.2) 60%, transparent 100%);
 468 |     display: flex; align-items: flex-end; padding: 20px;
 469 |     gap: 10px;
 470 |   }
 471 |   .work-badge {
 472 |     background: rgba(27,168,138,0.2);
 473 |     border: 1px solid var(--border-bright);
 474 |     backdrop-filter: blur(8px);
 475 |     border-radius: 6px; padding: 4px 10px;
 476 |     font-size: 0.7rem; color: var(--teal-light);
 477 |     letter-spacing: 0.08em; text-transform: uppercase;
 478 |   }
 479 |   .work-actions {
 480 |     position: absolute; inset: 0;
 481 |     background: rgba(8,14,18,0.7);
 482 |     backdrop-filter: blur(4px);
 483 |     display: flex; align-items: center; justify-content: center;
 484 |     gap: 12px;
 485 |     opacity: 0; transition: opacity 0.35s;
 486 |   }
 487 |   .work-card:hover .work-actions { opacity: 1; }
 488 |   .action-btn {
 489 |     background: var(--surface);
 490 |     border: 1px solid var(--border-bright);
 491 |     border-radius: 50%; width: 48px; height: 48px;
 492 |     display: flex; align-items: center; justify-content: center;
 493 |     font-size: 1.1rem; color: var(--teal-light);
 494 |     transition: all 0.3s;
 495 |     transform: translateY(10px);
 496 |   }
 497 |   .work-card:hover .action-btn { transform: translateY(0); }
 498 |   .action-btn:nth-child(2) { transition-delay: 0.05s; }
 499 |   .action-btn:nth-child(3) { transition-delay: 0.1s; }
 500 |   .action-btn:hover {
 501 |     background: var(--teal-dark);
 502 |     border-color: var(--teal-light);
 503 |     transform: scale(1.1) translateY(0) !important;
 504 |     box-shadow: 0 8px 20px rgba(27,168,138,0.4);
 505 |   }
 506 | 
 507 |   .work-info { padding: 24px; }
 508 |   .work-title {
 509 |     font-family: var(--font-main); font-size: 1.1rem; font-weight: 700;
 510 |     margin-bottom: 8px; color: var(--text);
 511 |     transition: color 0.3s;
 512 |   }
 513 |   .work-card:hover .work-title { color: var(--teal-light); }
 514 |   .work-desc {
 515 |     font-size: 0.87rem; line-height: 1.65; color: var(--text-dim);
 516 |     margin-bottom: 16px;
 517 |   }
 518 |   .work-tags { display: flex; gap: 6px; flex-wrap: wrap; }
 519 |   .wtag {
 520 |     background: var(--surface2); border: 1px solid var(--border);
 521 |     border-radius: 100px; padding: 3px 10px;
 522 |     font-size: 0.7rem; color: var(--teal); letter-spacing: 0.08em;
 523 |   }
 524 | 
 525 |   /* MODAL */
 526 |   .modal-overlay {
 527 |     position: fixed; inset: 0; z-index: 9000;
 528 |     background: rgba(4,10,14,0.92);
 529 |     backdrop-filter: blur(20px);
