1245 |       const rect = card.getBoundingClientRect();
1246 |       const cx = rect.left + rect.width / 2;
1247 |       const cy = rect.top + rect.height / 2;
1248 |       const rx = -(e.clientY - cy) / rect.height * 10;
1249 |       const ry = (e.clientX - cx) / rect.width * 10;
1250 |       card.style.transform = `perspective(800px) rotateX(${rx}deg) rotateY(${ry}deg) translateY(-8px)`;
1251 |     });
1252 |     card.addEventListener('mouseleave', () => {
1253 |       card.style.transform = '';
1254 |     });
1255 |   });
