  23 |     --text: #E8F0F5;
  24 |     --text-dim: #7BA3B8;
  25 |     --text-faint: #3D6478;
  26 |     --border: rgba(27, 168, 138, 0.2);
  27 |     --border-bright: rgba(27, 168, 138, 0.5);
  28 |     --font-main: 'Syne', sans-serif;
  29 |     --font-body: 'DM Sans', sans-serif;
  30 |     --font-ar: 'Noto Kufi Arabic', sans-serif;
  31 |   }
  32 | 
  33 |   /* ===== RESET ===== */
  34 |   *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  35 |   html { scroll-behavior: smooth; }
  36 |   body {
  37 |     background: var(--bg);
  38 |     color: var(--text);
  39 |     font-family: var(--font-body);
  40 |     overflow-x: hidden;
  41 |   }
  42 |   a { color: inherit; text-decoration: none; }
  43 |   img { max-width: 100%; display: block; }
  44 | 
  45 | 
  46 |   /* ===== CANVAS BACKGROUND ===== */
  47 |   #bg-canvas {
  48 |     position: fixed; inset: 0;
  49 |     z-index: 0; pointer-events: none;
  50 |     opacity: 0.35;
  51 |   }
  52 | 
  53 |   /* ===== SCROLLBAR ===== */
  54 |   ::-webkit-scrollbar { width: 4px; }
  55 |   ::-webkit-scrollbar-track { background: var(--bg); }
  56 |   ::-webkit-scrollbar-thumb { background: var(--teal-dark); border-radius: 2px; }
  57 | 
  58 |   /* ===== SCROLL PROGRESS ===== */
  59 |   #scroll-progress {
  60 |     position: fixed; top: 0; left: 0;
  61 |     height: 2px; background: linear-gradient(90deg, var(--teal-dark), var(--teal-light));
  62 |     z-index: 999; transition: width 0.1s;
  63 |   }
  64 | 
  65 |   /* ===== NAVIGATION ===== */
  66 |   nav {
  67 |     position: fixed; top: 0; left: 0; right: 0;
  68 |     z-index: 100;
  69 |     padding: 0 clamp(20px, 5vw, 80px);
  70 |     height: 72px;
  71 |     display: flex; align-items: center; justify-content: space-between;
  72 |     background: rgba(8, 14, 18, 0.75);
  73 |     backdrop-filter: blur(20px);
  74 |     border-bottom: 1px solid var(--border);
  75 |     transition: all 0.4s;
  76 |   }
  77 |   nav.scrolled {
  78 |     height: 60px;
  79 |     border-bottom-color: var(--border-bright);
  80 |     box-shadow: 0 8px 40px rgba(0,0,0,0.4);
  81 |   }
  82 |   .nav-logo {
  83 |     height: 100px;
  84 |     filter: drop-shadow(0 0 12px rgba(27, 168, 138, 0.5));
  85 |     transition: filter 0.3s;
  86 |   }
  87 |   .nav-logo:hover { filter: drop-shadow(0 0 20px rgba(36, 212, 175, 0.7)); }
  88 |   .nav-links {
  89 |     display: flex; gap: 32px; list-style: none;
  90 |     align-items: center;
  91 |   }
  92 |   .nav-links a {
  93 |     font-family: var(--font-main);
  94 |     font-size: 0.85rem; font-weight: 600;
  95 |     letter-spacing: 0.08em;
  96 |     color: var(--text-dim);
  97 |     text-transform: uppercase;
  98 |     position: relative;
  99 |     transition: color 0.3s;
 100 |   }
 101 |   .nav-links a::after {
 102 |     content: ''; position: absolute; bottom: -4px; left: 0; right: 0;
 103 |     height: 1px; background: var(--teal-light);
 104 |     transform: scaleX(0); transform-origin: left;
 105 |     transition: transform 0.35s cubic-bezier(0.23,1,0.32,1);
 106 |   }
 107 |   .nav-links a:hover { color: var(--teal-light); }
 108 |   .nav-links a:hover::after { transform: scaleX(1); }
 109 | 
 110 |   .lang-switcher {
 111 |     display: flex; gap: 6px; align-items: center;
 112 |   }
 113 |   .lang-btn {
 114 |     background: none; border: 1px solid var(--border);
 115 |     color: var(--text-dim);
 116 |     padding: 4px 10px; border-radius: 20px;
 117 |     font-family: var(--font-body); font-size: 0.75rem;
 118 |     transition: all 0.3s;
 119 |   }
 120 |   .lang-btn.active, .lang-btn:hover {
 121 |     background: var(--teal-dark); border-color: var(--teal);
 122 |     color: var(--text);
 123 |   }
 124 | 
 125 |   .hamburger {
 126 |     display: none; flex-direction: column; gap: 5px;
 127 |     background: none; border: none; padding: 4px;
 128 |   }
 129 |   .hamburger span {
 130 |     display: block; width: 24px; height: 2px;
 131 |     background: var(--teal); border-radius: 2px;
 132 |     transition: all 0.35s;
 133 |   }
 134 |   .mobile-menu {
 135 |     display: none; position: fixed;
 136 |     top: 72px; left: 0; right: 0; bottom: 0;
 137 |     background: rgba(8,14,18,0.97);
 138 |     backdrop-filter: blur(30px);
 139 |     z-index: 99;
 140 |     flex-direction: column; align-items: center; justify-content: center;
 141 |     gap: 36px;
 142 |   }
 143 |   .mobile-menu.open { display: flex; }
 144 |   .mobile-menu a {
 145 |     font-family: var(--font-main);
 146 |     font-size: 2rem; font-weight: 700;
 147 |     color: var(--text-dim); letter-spacing: 0.05em;
 148 |     transition: color 0.3s;
 149 |   }
 150 |   .mobile-menu a:hover { color: var(--teal-light); }
 151 | 
 152 |   /* ===== SECTION BASE ===== */
 153 |   section {
 154 |     position: relative; z-index: 1;
 155 |     overflow: hidden;
 156 |   }
 157 | 
 158 |   /* ===== HERO ===== */
 159 |   #hero {
 160 |     min-height: 100vh;
 161 |     display: flex; flex-direction: column;
 162 |     align-items: center; justify-content: center;
 163 |     padding: 100px clamp(20px, 8vw, 140px) 80px;
 164 |     text-align: center;
 165 |   }
 166 |   .hero-eyebrow {
 167 |     display: inline-flex; align-items: center; gap: 10px;
 168 |     background: var(--surface2);
 169 |     border: 1px solid var(--border);
 170 |     border-radius: 100px;
 171 |     padding: 6px 18px;
 172 |     font-size: 0.78rem; font-weight: 500; letter-spacing: 0.12em;
 173 |     color: var(--teal-light); text-transform: uppercase;
 174 |     margin-bottom: 32px;
 175 |     opacity: 0; transform: translateY(20px);
 176 |     animation: fadeUp 0.8s 0.2s forwards;
