 212 |     50% { opacity: 1; transform: scaleX(1); }
 213 |   }
 214 | 
 215 |   .hero-desc {
 216 |     font-size: clamp(1rem, 2vw, 1.25rem);
 217 |     line-height: 1.75;
 218 |     color: var(--text-dim);
