 224 | 
 225 |   .hero-cta {
 226 |     display: flex; gap: 16px; flex-wrap: wrap; justify-content: center;
 227 |     opacity: 0; transform: translateY(20px);
 228 |     animation: fadeUp 0.9s 0.8s forwards;
 229 |   }
 230 |   .btn-primary {
 231 |     background: linear-gradient(135deg, var(--teal), var(--teal-dark));
 232 |     color: #fff; border: none;
 233 |     padding: 14px 36px; border-radius: 6px;
