 238 |     box-shadow: 0 0 30px rgba(27,168,138,0.3);
 239 |   }
 240 |   .btn-primary::before {
 241 |     content: '';
 242 |     position: absolute; inset: 0;
 243 |     background: linear-gradient(135deg, var(--teal-light), var(--teal));
 244 |     opacity: 0; transition: opacity 0.35s;
