 246 |   .btn-primary:hover { transform: translateY(-3px); box-shadow: 0 8px 40px rgba(27,168,138,0.5); }
 247 |   .btn-primary:hover::before { opacity: 1; }
 248 |   .btn-primary span { position: relative; z-index: 1; }
 249 | 
 250 |   .btn-ghost {
 251 |     background: none;
 252 |     border: 1px solid var(--border-bright);
 253 |     color: var(--text); padding: 14px 36px; border-radius: 6px;
 254 |     font-family: var(--font-main); font-size: 0.9rem; font-weight: 600;
 255 |     letter-spacing: 0.06em; text-transform: uppercase;
 256 |     transition: all 0.35s;
 257 |   }
 258 |   .btn-ghost:hover {
 259 |     background: var(--surface2);
 260 |     border-color: var(--teal-light);
 261 |     color: var(--teal-light);
 262 |     transform: translateY(-3px);
