 309 |   .delay-1 { transition-delay: 0.1s; }
 310 |   .delay-2 { transition-delay: 0.2s; }
 311 |   .delay-3 { transition-delay: 0.3s; }
 312 |   .delay-4 { transition-delay: 0.4s; }
 313 |   .delay-5 { transition-delay: 0.5s; }
 314 |   .delay-6 { transition-delay: 0.6s; }
