1175 | /* ==========================================
1176 |    CANVAS BACKGROUND — NETWORK PARTICLES
1177 |    ========================================== */
1178 | function initCanvas() {
1179 |   const canvas = document.getElementById('bg-canvas');
1180 |   const ctx = canvas.getContext('2d');
1181 |   let W, H, particles = [];
1182 | 
1183 |   function resize() {
1184 |     W = canvas.width = window.innerWidth;
1185 |     H = canvas.height = window.innerHeight;
1186 |   }
1187 |   resize();
1188 |   window.addEventListener('resize', resize);
1189 | 
1190 |   const N = 70;
1191 |   for (let i = 0; i < N; i++) {
1192 |     particles.push({
1193 |       x: Math.random() * W,
1194 |       y: Math.random() * H,
1195 |       vx: (Math.random() - 0.5) * 0.4,
1196 |       vy: (Math.random() - 0.5) * 0.4,
1197 |       r: Math.random() * 2 + 1
1198 |     });
1199 |   }
1200 | 
1201 |   function draw() {
1202 |     ctx.clearRect(0, 0, W, H);
1203 |     // Update
1204 |     particles.forEach(p => {
1205 |       p.x += p.vx; p.y += p.vy;
1206 |       if (p.x < 0 || p.x > W) p.vx *= -1;
1207 |       if (p.y < 0 || p.y > H) p.vy *= -1;
1208 |     });
1209 |     // Lines
1210 |     for (let i = 0; i < N; i++) {
1211 |       for (let j = i + 1; j < N; j++) {
1212 |         const dx = particles[i].x - particles[j].x;
1213 |         const dy = particles[i].y - particles[j].y;
1214 |         const dist = Math.sqrt(dx*dx + dy*dy);
1215 |         if (dist < 140) {
1216 |           const alpha = (1 - dist / 140) * 0.35;
1217 |           ctx.beginPath();
1218 |           ctx.strokeStyle = `rgba(27,168,138,${alpha})`;
1219 |           ctx.lineWidth = 0.7;
1220 |           ctx.moveTo(particles[i].x, particles[i].y);
1221 |           ctx.lineTo(particles[j].x, particles[j].y);
1222 |           ctx.stroke();
1223 |         }
1224 |       }
1225 |     }
1226 |     // Dots
1227 |     particles.forEach(p => {
1228 |       ctx.beginPath();
1229 |       ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
1230 |       ctx.fillStyle = 'rgba(27,168,138,0.5)';
1231 |       ctx.fill();
1232 |     });
1233 |     requestAnimationFrame(draw);
1234 |   }
1235 |   draw();
1236 | }
